import React, { useState } from "react";

function App() {
  const [query, setQuery] = useState("");
  const [response, setResponse] = useState("");

  const handleSubmit = async () => {
    try {
      const res = await fetch("http://localhost:5000/api/query", {
        method: "POST",
        headers: {
          "Content-Type": "application/json"
        },
        body: JSON.stringify({ query })
      });

      const data = await res.json();

      setResponse(JSON.stringify(data, null, 2));

    } catch (err) {
      setResponse("Failed to connect to backend");
    }
  };

  return (
    <div style={styles.container}>
      <h1>AI Medical Research Assistant</h1>

      <input
        type="text"
        placeholder="Enter medical query..."
        value={query}
        onChange={(e) => setQuery(e.target.value)}
        style={styles.input}
      />

      <button onClick={handleSubmit} style={styles.button}>
        Submit
      </button>

      <pre style={styles.response}>
        {response}
      </pre>
    </div>
  );
}

const styles = {
  container: {
    padding: "40px",
    fontFamily: "Arial",
    textAlign: "center"
  },

  input: {
    width: "400px",
    padding: "12px",
    fontSize: "16px",
    marginRight: "10px"
  },

  button: {
    padding: "12px 20px",
    fontSize: "16px",
    cursor: "pointer"
  },

  response: {
    marginTop: "30px",
    textAlign: "left",
    background: "#f4f4f4",
    padding: "20px",
    borderRadius: "10px",
    maxWidth: "700px",
    marginInline: "auto"
  }
};

export default App;
